38	#[derive(Debug, Clone, Eq, PartialEq, Ord, PartialOrd)]
39	pub(crate) enum UnsupportedRuleReason {
40	    /// The rule is stylistic and is fundamentally incompatible with the formatter, and there's no formatter option to adjust its behavior.
41	    ///
42	    /// This is for rules that enforce formatting that are at odds with Biome's formatting decisions.
43	    Stylistic,
44	    /// The formatter completely covers the functionality that the rule is meant to enforce (assuming default rule options).
45	    ///
46	    /// The rule is therefore redundant when using the formatter, and losing the rule does not reduce code quality.
47	    FormatterCovers,
48	    /// The functionality is covered by a Biome formatter option.
49	    FormatterOption(&'static str),
50	    /// The rule belongs to a known source, but it is not yet implemented in Biome.
51	    KnownSourceNotImplemented,
52	    /// The rule belongs to an unknown source, and is therefore not implemented in Biome.
53	    UnknownSource,
54	}
55	
56	impl Display for UnsupportedRuleReason {
57	    fn fmt(&self, fmt: &mut biome_console::fmt::Formatter) -> std::io::Result<()> {
58	        match self {
59	            Self::Stylistic => {
60	                fmt.write_markup(markup! { "Stylistic, incompatible with formatter." })
61	            }
62	            Self::FormatterCovers => {
63	                fmt.write_markup(markup! { "Redundant, completely covered by Biome's formatter." })
64	            }
65	            Self::FormatterOption(option) => fmt.write_markup(
66	                markup! { "Covered by Biome's "<Emphasis>{option}</Emphasis>" formatter option." },
67	            ),
68	            Self::KnownSourceNotImplemented => {
69	                fmt.write_markup(markup! { "Known source, not yet implemented." })
70	            }
71	            Self::UnknownSource => fmt.write_markup(markup! {
72	                "These rules originate from an eslint plugin or other tool that Biome doesn't know about."
73	            }),
74	        }
75	    }
76	}
