pub(crate) fn merge_biome_config_with_eslint(
    mut biome_config: biome_config::Configuration,
    eslint_config: eslint_eslint::AnyConfigData,
    options: &MigrationOptions,
) -> (biome_config::Configuration, MigrationResults) {
