+                                level: severity.into(),
+                                fix: None,
+                                options: options.into(),
+                            },
+                        ));
+                }
+            }
+        }
+        eslint_eslint::Rule::UnicornFilenameCase(conf) => {
+            if migrate_eslint_any_rule(rules, &name, conf.severity(), opts, results) {
+                let group = rules.style.get_or_insert_with(Default::default);
